-- ForeverSensei_Paladin/Locales/en.lua: English source text of the Paladin pack (skills, talents, guide and the
-- class-specific interface lines the core shows). Every line has a stable id; Locales/ja.lua translates the same ids.
-- Facts come from WoW: Forever sources only (see SOURCES.md and the src fields in Data/*.lua).
-- Placeholders are {name}; the Japanese must use the same ones. The core looks these up before its own texts.
local _, P = ...

P.locales = P.locales or {}
P.localeOrder = {}
local data = {}
P.locales.en = data
-- Proxy that records the order of ids (the review tab walks them in this order, before the core's ids).
local L = setmetatable({}, { __newindex = function(_, k, v)
  if data[k] == nil then table.insert(P.localeOrder, k) end
  data[k] = v
end })

---------------------------------------------------------------------------------------------------
-- Skills: what = what it does (facts), when = when to use it (advice).
---------------------------------------------------------------------------------------------------
L["spell.devotion_aura.what"] = "An aura that gives more armor to party members within 30 yards. Each player can have only one aura from you."
L["spell.devotion_aura.when"] = "Use it before you learn Retribution Aura, or when another paladin already runs Retribution Aura."
L["spell.seal_of_righteousness.what"] = "A seal for 30 seconds: each melee hit deals extra Holy damage, more with a slow weapon. Its Judgement deals Holy damage."
L["spell.seal_of_righteousness.when"] = "Your damage seal before Seal of Fury, and when you don't want Judgement to taunt."
L["spell.holy_light.what"] = "A big heal on one friendly target, up to 40 yards away. 2.5-second cast."
L["spell.holy_light.when"] = "Heal yourself between fights when questing alone. In a group, leave the healing to your healer."
L["spell.blessing_of_might.what"] = "A blessing for 1 hour: more melee attack power. Each player can have only one blessing from you."
L["spell.blessing_of_might.when"] = "Give it to warriors, rogues and other melee fighters before the pull."
L["spell.judgement.what"] = "Releases your seal's energy on an enemy within 10 yards. It doesn't use up the seal and doesn't trigger the global cooldown. 10-second cooldown."
L["spell.judgement.when"] = "Use it on cooldown while tanking. With Seal of Fury it also taunts the enemy."
L["spell.divine_protection.what"] = "Makes you immune to all attacks and spells for 6 seconds, but you can't attack. Applies Forbearance. 5-minute cooldown."
L["spell.divine_protection.when"] = "A last resort: enemies stop attacking you. Taunt them back afterwards."
L["spell.holy_strike.what"] = "An instant melee strike: part of your weapon damage plus Holy damage. 10-second cooldown."
L["spell.holy_strike.when"] = "Press it every time it is ready. It is one of your main threat buttons."
L["spell.seal_of_the_crusader.what"] = "A seal for 30 seconds: more attack power and 40% faster but weaker hits. Its Judgement makes the enemy take more Holy damage for 40 seconds."
L["spell.seal_of_the_crusader.when"] = "Judge it first on an enemy that lives longer than about 20 seconds, then switch to Seal of Fury."
L["spell.hammer_of_justice.what"] = "Stuns an enemy for 3 seconds. 10 yards, 1-minute cooldown."
L["spell.hammer_of_justice.when"] = "You have no interrupt: use it to stop a dangerous enemy cast, or to stop an enemy that runs to your healer."
L["spell.purify.what"] = "Removes 1 disease and 1 poison effect from a friendly target."
L["spell.purify.when"] = "Use it when a party member has a harmful poison or disease and you have mana to spare."
L["spell.lay_on_hands.what"] = "Heals a friendly target for your maximum health, but drains all your mana. 20-minute cooldown, 40 yards."
L["spell.lay_on_hands.when"] = "Save it for an emergency, when someone would otherwise die."
L["spell.blessing_of_protection.what"] = "Makes a party member immune to physical attacks for 6 seconds, but they can't attack. Applies Forbearance."
L["spell.blessing_of_protection.when"] = "Use it on a party member who takes deadly physical hits. With no one under the mouse and no friendly target it goes on you: you can't attack for 6 seconds and get Forbearance."
L["spell.seal_of_fury.what"] = "Your tank seal for 30 seconds: extra Holy damage on each hit, and with a shield an absorb shield. Its Judgement taunts the enemy for 3 seconds."
L["spell.seal_of_fury.when"] = "Keep it on whenever you tank. Refresh it before it runs out."
L["spell.righteous_fury.what"] = "For 30 minutes, all your threat is 33% higher and your Holy threat is 90% higher on top."
L["spell.righteous_fury.when"] = "Cast it before every dungeon pull while you tank, and again when it runs out."
L["spell.redemption.what"] = "Brings a dead player back to life. 10-second cast, only out of combat."
L["spell.redemption.when"] = "Use it after a fight to bring back a party member who died."
L["spell.blessing_of_wisdom.what"] = "A blessing for 1 hour: restores mana every 5 seconds."
L["spell.blessing_of_wisdom.when"] = "Give it to healers and casters, and to yourself when your mana runs low."
L["spell.retribution_aura.what"] = "An aura that deals Holy damage to every enemy that hits a party member within 30 yards."
L["spell.retribution_aura.when"] = "Your main tank aura: it builds threat on every enemy that hits your group."
L["spell.blessing_of_freedom.what"] = "Makes a friendly target immune to movement-slowing effects for 10 seconds. 20-second cooldown."
L["spell.blessing_of_freedom.when"] = "Use it on someone who is slowed or rooted, or on yourself to reach an enemy."
L["spell.exorcism.what"] = "Instant Holy damage to one Undead or Demon enemy. 30 yards, 15-second cooldown."
L["spell.exorcism.when"] = "Open with it against undead and demons, then use it on cooldown."
L["spell.flash_of_light.what"] = "A quick, small heal on one friendly target, up to 40 yards away. 1.5-second cast."
L["spell.flash_of_light.when"] = "Heal yourself or a party member in a pinch. Your healer does most of the healing."
L["spell.consecration.what"] = "Holy damage on the ground under you for 8 seconds. The first 4 enemies in it take extra damage. 8-second cooldown."
L["spell.consecration.when"] = "Use it when you fight several enemies. Stand still on it so it keeps hitting."
L["spell.blessing_of_kings.what"] = "A blessing for 1 hour: 10% more stats. Learned from the trainer at level 20."
L["spell.blessing_of_kings.when"] = "Give it to yourself and to players who don't get a better blessing from you."
L["spell.voice_of_truth.what"] = "Makes you immune to silence and interrupt effects for 6 seconds. 3-minute cooldown."
L["spell.voice_of_truth.when"] = "Use it before a long cast that an enemy may interrupt, like Holy Light or Redemption."
L["spell.concentration_aura.what"] = "An aura that gives party members within 30 yards a 35% chance to keep casting when they are hit."
L["spell.concentration_aura.when"] = "Use it when you heal yourself while enemies hit you, or when a group without a tank aura needs it."
L["spell.seal_of_justice.what"] = "A seal for 30 seconds: each hit may stun for 2 seconds. Its Judgement stops the enemy from fleeing for 10 seconds."
L["spell.seal_of_justice.when"] = "Judge it on an enemy that runs away at low health."
L["spell.turn_undead.what"] = "Makes one undead enemy flee for up to 10 seconds. Damage may break it. 1.5-second cast, 20 yards."
L["spell.turn_undead.when"] = "Use it on an extra undead enemy that nobody attacks, to fight one at a time."
L["spell.shadow_resistance_aura.what"] = "An aura that gives party members within 30 yards 30 Shadow resistance."
L["spell.shadow_resistance_aura.when"] = "Switch to it before a boss that deals a lot of Shadow damage."
L["spell.divine_intervention.what"] = "You die to protect a party member: enemies stop attacking them, but they can't act for 3 minutes. Needs a Symbol of Divinity. 1-hour cooldown."
L["spell.divine_intervention.when"] = "Use it in a wipe, so the saved player can bring the group back."
L["spell.seal_of_light.what"] = "A seal for 30 seconds: each hit may heal you. Its Judgement lets the enemy's attackers heal themselves."
L["spell.seal_of_light.when"] = "Use it when questing alone to save mana on healing."
L["spell.templars_bulwark.what"] = "Talent. Absorbs damage equal to your maximum health for 8 seconds. Applies Forbearance. 5-minute cooldown."
L["spell.templars_bulwark.when"] = "Your first emergency button: you keep tanking while it absorbs the hits."
L["spell.frost_resistance_aura.what"] = "An aura that gives party members within 30 yards 30 Frost resistance."
L["spell.frost_resistance_aura.when"] = "Switch to it before a boss that deals a lot of Frost damage."
L["spell.divine_shield.what"] = "Makes you immune to all damage and spells for 10 seconds, but you deal 50% less damage. Applies Forbearance. 5-minute cooldown."
L["spell.divine_shield.when"] = "A last resort: enemies stop attacking you. Taunt them back afterwards."
L["spell.fire_resistance_aura.what"] = "An aura that gives party members within 30 yards 30 Fire resistance."
L["spell.fire_resistance_aura.when"] = "Switch to it before a boss that deals a lot of Fire damage."
L["spell.swift_judgement.what"] = "Talent. A second Judgement with its own 1-minute cooldown. It doesn't share a cooldown with Judgement."
L["spell.swift_judgement.when"] = "Use it right after Judgement at the start of a pull, or to taunt again with Seal of Fury."
L["spell.seal_of_wisdom.what"] = "A seal for 30 seconds: each hit may restore mana. Its Judgement lets the enemy's attackers restore mana."
L["spell.seal_of_wisdom.when"] = "Judge it first on a long fight when your group needs mana, then switch to Seal of Fury."
L["spell.summon_warhorse.what"] = "Summons your warhorse mount. 3-second cast."
L["spell.summon_warhorse.when"] = "Use it to travel. Cast it from the spellbook or drag it to a free button."
L["spell.holy_shield.what"] = "Talent. Raises your block chance by 30% for 10 seconds, up to 4 blocks. Each block deals Holy damage with extra threat. 10-second cooldown."
L["spell.holy_shield.when"] = "Keep it up all the time while tanking. Cast it right before the pull."
L["spell.cleanse.what"] = "Removes 1 poison, 1 disease and 1 magic effect from a friendly target."
L["spell.cleanse.when"] = "Use it in the gaps of your rotation on a party member with a harmful effect."
L["spell.hammer_of_wrath.what"] = "Holy damage to an enemy at 20% health or less. 1-second cast, 30 yards, 6-second cooldown."
L["spell.hammer_of_wrath.when"] = "Finish an enemy with it when you tank only one enemy."
L["spell.blessing_of_sacrifice.what"] = "A blessing for 30 seconds: part of the damage of each hit on a party member goes to you instead."
L["spell.blessing_of_sacrifice.when"] = "Use it on a party member who takes hits, or before a stun or disorient on them."
L["spell.holy_wrath.what"] = "Holy damage and a 2-second stun on all undead and demons within 20 yards. 2-second cast, 1-minute cooldown."
L["spell.holy_wrath.when"] = "Use it against groups of undead or demons."
L["spell.greater_blessing_of_might.what"] = "Gives Blessing of Might's effect for 1 hour to everyone in the group of the target's class. Needs a Symbol of Kings."
L["spell.greater_blessing_of_might.when"] = "Use it in a raid to bless all melee players of one class at once."
L["spell.greater_blessing_of_wisdom.what"] = "Gives Blessing of Wisdom's effect for 1 hour to everyone in the group of the target's class. Needs a Symbol of Kings."
L["spell.greater_blessing_of_wisdom.when"] = "Use it in a raid to bless all healers or casters of one class at once."
L["spell.greater_blessing_of_kings.what"] = "Gives 10% more stats for 1 hour to everyone in the group of the target's class. Needs a Symbol of Kings."
L["spell.greater_blessing_of_kings.when"] = "Use it in a raid to bless a whole class at once."
L["spell.summon_charger.what"] = "Summons your charger, a faster mount. 3-second cast."
L["spell.summon_charger.when"] = "Use it to travel instead of the warhorse."

---------------------------------------------------------------------------------------------------
-- Talents: why this talent is in the plan.
---------------------------------------------------------------------------------------------------
L["talent.benediction.why"] = "Your instant spells cost 10% less mana. Almost all your tank spells are instant."
L["talent.sanctified_judgement.why"] = "Judgement gives back 60% of the mana cost of your seal. Good mana while you tank one enemy."
L["talent.conviction.why"] = "More critical strike chance for all your spells and attacks."
L["talent.pursuit_of_justice.why"] = "You run 15% faster, also on a mount. It doesn't add to other speed effects."
L["talent.redoubt.why"] = "Enemy hits may raise your block chance for a short time. More blocks mean less damage."
L["talent.precision.why"] = "More hit chance, so fewer of your attacks miss."
L["talent.guardians_favor.why"] = "Blessing of Protection gets a 1-minute shorter cooldown and Blessing of Freedom lasts 3 seconds longer."
L["talent.templars_bulwark.why"] = "Gives you Templar's Bulwark, an absorb shield equal to your maximum health."
L["talent.shield_specialization.why"] = "Your shield absorbs more, and your blocks restore mana (once every 3 seconds). More enemies give more mana."
L["talent.toughness.why"] = "More armor from your items."
L["talent.swift_judgement.why"] = "Gives you Swift Judgement: a second Judgement for the start of a pull, or a second taunt."
L["talent.improved_righteous_fury.why"] = "While Righteous Fury is on, you take less damage."
L["talent.holy_shield.why"] = "Gives you Holy Shield: more blocks and Holy damage with extra threat."
L["talent.reckoning.why"] = "Blocks and critical hits on you may give you extra attacks."
L["talent.iron_creed.why"] = "Holy Strike causes 30% more threat, and with Righteous Fury it also lowers your damage taken for 6 seconds."
L["talent.sacred_duty.why"] = "Divine Shield, Divine Protection and Templar's Bulwark come back 60 seconds sooner, and Forbearance is shorter."
L["talent.shieldsworn.why"] = "Holy Strike comes back 4 seconds sooner and strikes with your shield. It triggers Holy Shield and Shield Specialization and lets you block spells for 6 seconds."
L["talent.improved_judgement.why"] = "Judgement comes back sooner."
L["talent.vindication.why"] = "Your melee hits may lower the enemy's attack power, so it hits you less hard."
L["talent.sacred_arbiter.why"] = "Holy Strike deals 20% more damage and refreshes your Judgements on the enemy."
L["talent.note.order"] = "This addon follows the leveling order of the Wowhead Protection Paladin guide (0/32/19 at level 60). You get one point per level from level 10."
L["talent.note.moba"] = "The Mobalytics guide uses 0/35/16 with Anticipation. Those points can also go to Toughness or Guardian's Favor. Your buttons don't change either way."

---------------------------------------------------------------------------------------------------
-- Guide sections (Data/Protection/Guide.lua has the sources per paragraph).
---------------------------------------------------------------------------------------------------
L["guide.role.p1"] = "As a Protection Paladin you are the tank. Keep the enemies attacking you so the rest of the group can fight safely. Most of your threat comes from Holy damage."
L["guide.role.p2"] = "Righteous Fury raises all your threat by 33% and your Holy threat by another 90% for 30 minutes. Keep it on whenever you tank."
L["guide.role.p3"] = "Seal of Fury (level 10) is your tank seal. With a shield, each hit also gives you a small absorb shield. Its Judgement taunts the enemy for 3 seconds."
L["guide.role.p4"] = "Judgement doesn't trigger the global cooldown and reaches only 10 yards. Swift Judgement (talent, level 37) has its own cooldown, so you can judge twice in a row."
L["guide.role.p5"] = "Learn these from the trainer as soon as you can: Judgement at 4, Holy Strike at 6, Seal of Fury at 10, Retribution Aura at 16 and Consecration at 20."
L["guide.rotation.p1"] = "Before the pull: Seal of Fury (Shift+1), Holy Shield (3), and Consecration (2) where you will tank."
L["guide.rotation.p2"] = "One enemy: Exorcism first if it is undead or a demon. Then Judgement, Swift Judgement and Holy Strike: R does all three in one press. Then Consecration."
L["guide.rotation.p3"] = "Then repeat: keep Seal of Fury up and use Holy Shield, Holy Strike, Judgement, Exorcism (undead and demons), Consecration and Hammer of Wrath (enemy at 20% health or less)."
L["guide.rotation.p4"] = "Several enemies: spread your first threat. Exorcism on an undead or demon, Judgement on a second enemy, Swift Judgement on a third, Consecration, and Holy Strike on one you haven't judged."
L["guide.rotation.p5"] = "Mana: after you spend mana, normal regeneration pauses for 5 seconds. Use Judgement and Holy Strike together, and refresh your seal and Consecration in the same moment."
L["guide.rotation.p6"] = "You have no interrupt, so don't spam Consecration against casters. Hammer of Justice (F) stuns for 3 seconds. Use Hammer of Wrath (Shift+E, 1-second cast) when you tank one enemy or none."
L["guide.seals.p1"] = "A seal lasts 30 seconds, and only one can be active. Judgement releases the seal's energy on an enemy without using it up."
L["guide.seals.p2"] = "Seal of Fury (Shift+1): extra Holy damage on each hit, and with a shield an absorb shield of half that damage. Its Judgement deals Holy damage and taunts for 3 seconds."
L["guide.seals.p3"] = "Seal of Righteousness (Shift+2): extra Holy damage on each hit, more with a slow weapon. Its Judgement deals Holy damage but doesn't taunt."
L["guide.seals.p4"] = "Seal of the Crusader (Shift+3) and Seal of Wisdom (Shift+5): if the enemy lives longer than 20 to 30 seconds, judge one of them first (more Holy damage taken, or mana for attackers). Then switch to Seal of Fury."
L["guide.seals.p5"] = "Seal of Justice (Shift+4): hits may stun for 2 seconds, and its Judgement stops fleeing for 10 seconds. Seal of Light: hits may heal you. A tank rarely needs it, so click it on Action Bar 6."
L["guide.seals.p6"] = "Seal levels: Righteousness 1, Crusader 6, Fury 10, Justice 22, Light 30, Wisdom 38. Only one of your Judgements can be on an enemy at a time."
L["guide.auras.p1"] = "Your auras are on Action Bar 3: Ctrl+1 Retribution, Ctrl+2 Devotion, Ctrl+3 Concentration, Ctrl+4 Shadow Resistance and Ctrl+5 Frost Resistance Aura. Click Fire Resistance Aura on Action Bar 6. The stance bar still shows all of them."
L["guide.auras.p2"] = "Retribution Aura is your main aura: it deals Holy damage to every enemy that hits your group, which builds threat on big pulls. Use Devotion Aura only if another paladin runs Retribution Aura."
L["guide.auras.p3"] = "Concentration Aura gives a 35% chance to keep casting when you are hit. Use it when you must heal yourself while enemies hit you."
L["guide.auras.p4"] = "Shadow, Frost and Fire Resistance Aura each give 30 resistance to that school. Switch before a boss that deals a lot of that damage."
L["guide.auras.p5"] = "A blessing lasts 1 hour, and each player can have only one from you. Blessing of Kings (Ctrl+Z) gives 10% more stats. Blessing of Might is on Ctrl+X and Blessing of Wisdom on Ctrl+C. Click the Greater Blessings on Action Bar 4."
L["guide.cooldowns.p1"] = "Forbearance: Divine Shield, Divine Protection, Templar's Bulwark and Blessing of Protection apply it for 1 minute, and none of them works while it is on you."
L["guide.cooldowns.p2"] = "Templar's Bulwark (Shift+Z, talent at 32) absorbs damage equal to your maximum health for 8 seconds. You keep tanking, so it is your first emergency button."
L["guide.cooldowns.p3"] = "Divine Shield (Shift+X) and Divine Protection (Shift+C) make you immune, but enemies then stop attacking you. Taunt with Judgement under Seal of Fury first, then use them."
L["guide.cooldowns.p4"] = "Lay on Hands (Shift+Mouse 4) heals a friendly target for your maximum health but drains all your mana. 20-minute cooldown."
L["guide.cooldowns.p5"] = "Blessing of Protection (Mouse 4) protects a party member from physical attacks for 6 seconds. With no one under the mouse it goes on you: your attacks stop, and Forbearance blocks Templar's Bulwark, Divine Shield and Divine Protection for 1 minute. Blessing of Sacrifice (Ctrl+Mouse 4) moves part of each hit on them to you for 30 seconds."
L["guide.manners.p1"] = "Your main buttons don't fill every global cooldown. Use the gaps for Cleanse (Mouse 5) and Blessing of Freedom (Shift+Mouse 5) on your group."
L["guide.manners.p2"] = "Cleanse (level 42) removes 1 poison, 1 disease and 1 magic effect. Before 42, Purify removes 1 poison and 1 disease from the same button."
L["guide.manners.p3"] = "Redemption (click it on Action Bar 4) brings a dead player back after combat (10-second cast). Divine Intervention (Action Bar 6) saves one party member in a wipe, but you die."
L["guide.manners.p4"] = "Blessing of Freedom makes a party member immune to slowing effects for 10 seconds. Use it on someone who is slowed or rooted."
L["guide.manners.p5"] = "Turn Undead (Shift+F) makes one undead enemy flee for up to 10 seconds, and damage may break it. Use it only on an enemy nobody attacks."

---------------------------------------------------------------------------------------------------
-- Interface text that belongs to this class (the core's windows show it).
---------------------------------------------------------------------------------------------------
L["ui.where.totembar"] = "No bar slot: use it from the spellbook when needed."
L["ui.preview.warn.stance"] = "By default these keys use the stance bar: {key}. In this layout they cast your auras from Action Bar 3. The stance bar still shows your auras."
L["ui.layout.intro"] = "Without a modifier (Action Bar 1) are the spells you press most while tanking: 1 Holy Strike, 2 Consecration, 3 Holy Shield, 4 and 5 heals, Q Judgement, E Swift Judgement, R the opener, F Hammer of Justice, Z and X potions, C Righteous Fury."
L["ui.layout.intro2"] = "Shift (Action Bar 2) and Ctrl (Action Bar 3) are split into blocks: 1 to 5, Q to F, and Z to C. Shift: seals, attacks for undead and low-health enemies, Forbearance cooldowns. Ctrl: auras and blessings (Ctrl+Q to F are free). The mouse side buttons and the spells you click in combat are on Action Bar 6. Action Bar 4 is for clicking out of combat."
L["ui.layout.items"] = "Potions and Healthstones use macros that ForeverSensei keeps up to date: FS_HEALTH on Z (a Healthstone, else a Healing Potion) and FS_MANA on X. Each uses the best one in your bags for your level. If your bags change in combat, it is updated after combat."
L["ui.layout.changed"] = "The paladin key layout has changed: seals are now on Shift+1 to 5 (Seal of Justice on Shift+4), auras on Ctrl+1 to 5 (Action Bar 3), and the mouse side buttons moved to Action Bar 6. Your bars have not been changed. Press Apply full layout to see what would change first. Your current bars are saved, so you can undo it."
L["ui.layout.clean"] = "Empty the bars removes only the buttons this layout uses (and the ones the old layout put on Action Bar 5). Free buttons and buttons this layout doesn't use stay. Your bars are saved first, so Undo puts them back."
L["ui.targeting.mouseover.help"] = "Point the mouse at a player (on the party frames or in the world) and press the key. Without a mouseover it uses your friendly target, else you (Blessing of Protection too). Blessing of Sacrifice never falls back to you. Hammer of Justice hits the enemy under the mouse, else your target."
L["ui.targeting.click.help"] = "Click a player first to target them, then press the key. Hammer of Justice and the opener on R stay macros."
L["ui.trainer.title"] = "At the Paladin trainer"
L["ui.trainer.intro"] = "Skills you can learn now from a Paladin trainer. If the trainer doesn't have one, it may come from a class quest."
L["ui.talents.intro"] = "Talent order from the Wowhead Protection Paladin leveling guide. You get one point per level from level 10."
L["ui.role.tank"] = "Tanking"
L["ui.combo.opener"] = "Opener (Judgement, Swift Judgement and Holy Strike)"
L["ui.tab.role"] = "Role and threat"
L["ui.tab.rotation"] = "Rotation"
L["ui.tab.seals"] = "Seals and Judgement"
L["ui.tab.auras"] = "Auras and blessings"
L["ui.tab.cooldowns"] = "Cooldowns"
L["ui.tab.manners"] = "Group manners"
